package com.flowdesk.alert.recovery;
import com.flowdesk.common.web.ApiException;import org.springframework.http.HttpHeaders;import org.springframework.http.HttpStatus;import java.util.List;import java.util.Map;import java.util.regex.Pattern;
final class AlertRecoverySupport{private static final Pattern KEY=Pattern.compile("^[A-Za-z0-9._:-]{16,128}$"),ETAG=Pattern.compile("^\"lv:([0-9]+)\"$");private AlertRecoverySupport(){}
    static String reason(String v){if(v==null||v.isBlank()||!validText(v,1000))throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,"RECOVERY_REASON_REQUIRED","人工重放必须提供 1 到 1000 个字符的原因。",false);return v;}
    static String key(String v){if(v==null||v.isBlank())throw ApiException.badRequest("IDEMPOTENCY_KEY_REQUIRED","命令必须携带 Idempotency-Key。");if(!KEY.matcher(v).matches())throw ApiException.badRequest("IDEMPOTENCY_KEY_INVALID","Idempotency-Key 格式无效。");return v;}
    static long version(String v){if(v==null||v.isBlank())throw ApiException.preconditionRequired("人工重放必须携带 If-Match。");var m=ETAG.matcher(v.trim());if(!m.matches())throw ApiException.badRequest("PRECONDITION_INVALID","If-Match 必须是单个强 ETag。");try{return Long.parseLong(m.group(1));}catch(Exception e){throw ApiException.badRequest("PRECONDITION_INVALID","If-Match 版本无效。");}}
    private static boolean validText(String v,int max){int count=v.codePointCount(0,v.length());if(count<1||count>max)return false;for(int i=0;i<v.length();){char c=v.charAt(i);if(Character.isSurrogate(c)){if(!Character.isHighSurrogate(c)||i+1>=v.length()||!Character.isLowSurrogate(v.charAt(i+1)))return false;i+=2;continue;}if(c!='\t'&&c!='\n'&&c!='\r'&&Character.isISOControl(c))return false;i++;}return true;}
    static String etag(long v){return "\"lv:"+v+"\"";}static ApiException versionConflict(long v){return new ApiException(org.springframework.http.HttpStatusCode.valueOf(412),"RESOURCE_VERSION_CONFLICT","恢复记录已更新，请刷新后重试。",false,List.of(),Map.of(HttpHeaders.ETAG,etag(v)));}}
